        { id: "l21k6", type: "count", front: "تشكيل المجلس الدستوري الفرنسي", n: 2, lead: "يتشكل من فئتين:", items: ["رؤساء الجمهورية السابقون: أعضاء بحكم القانون مدى الحياة", "تسعة أعضاء يُعيَّنون لتسع سنوات غير قابلة للتجديد، ويتجدد الثلث كل ثلاث سنوات"], pg: "118" },
        { id: "l21k7", type: "count", front: "من يعيّن الأعضاء التسعة في المجلس الدستوري الفرنسي؟", n: 3, lead: "ثلاث جهات، لكل منها ثلاثة أعضاء:", items: ["رئيس الجمهورية", "رئيس الجمعية الوطنية", "رئيس مجلس الشيوخ"], pg: "118" },
        { id: "l21k8", type: "count", front: "من يطلب نظر المجلس الدستوري الفرنسي في قانون قبل صدوره؟", n: 3, lead: "بناءً على طلب من:", items: ["رئيس الجمهورية", "رئيس الوزراء", "أحد رئيسي مجلسي البرلمان"], pg: "118–119" },
        { id: "l21k9", type: "count", front: "آثار قرار المجلس الدستوري الفرنسي بعدم دستورية قانون", n: 3, lead: "ثلاثة آثار:", items: ["عدم إصدار القانون أو تطبيقه", "عدم قابلية القرار للطعن بأي أسلوب من الأساليب", "إلزامه لجميع هيئات الدولة وسلطاتها"], pg: "118–119" },
        { id: "l21k10", type: "rule", front: "سبب أخذ فرنسا بالرقابة السياسية", rule: "اتهام رجال الثورة الفرنسية للقضاة بمحاباة النظام السائد قبل الثورة على حساب الدستور، ويرى مؤيدوها أن تدخل القضاء يتنافى مع مبدأ فصل السلطات.", exc: "ومع ذلك لم تترسخ جذور الرقابة السياسية في فرنسا إلا في مراحل متأخرة.", pg: "119" }
